import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    static int lowerBound(long[] a, long x) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        int q = nextInt();
        long[][] ops = new long[q][3];
        int k = 0;
        for (long[] op : ops) {
            op[0] = nextLong();
            op[1] = nextLong();
            if (op[0] == 1) k++;
            else op[2] = nextLong();
        }
        // Compress the obstacle coordinates; a Fenwick tree counts inserted ones.
        long[] coords = new long[k];
        k = 0;
        for (long[] op : ops) if (op[0] == 1) coords[k++] = op[1];
        Arrays.sort(coords);
        int[] bit = new int[k + 1];
        StringBuilder out = new StringBuilder();
        for (long[] op : ops) {
            if (op[0] == 1) {
                for (int i = lowerBound(coords, op[1]) + 1; i <= k; i += i & -i) bit[i]++;
            } else {
                long x = op[1], size = op[2];
                // Obstacles inside [x - size, x - 1].
                int left = lowerBound(coords, x - size), right = lowerBound(coords, x);
                int count = 0;
                for (int i = right; i > 0; i -= i & -i) count += bit[i];
                for (int i = left; i > 0; i -= i & -i) count -= bit[i];
                out.append(count == 0 ? '1' : '0');
            }
        }
        System.out.println(out);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	q := nextInt()
	ops := make([][3]int, q)
	coords := []int{}
	for i := range ops {
		ops[i][0], ops[i][1] = nextInt(), nextInt()
		if ops[i][0] == 1 {
			coords = append(coords, ops[i][1])
		} else {
			ops[i][2] = nextInt()
		}
	}
	// Compress the obstacle coordinates; a Fenwick tree counts inserted ones.
	sort.Ints(coords)
	bit := make([]int, len(coords)+1)
	prefix := func(i int) int {
		total := 0
		for ; i > 0; i -= i & -i {
			total += bit[i]
		}
		return total
	}
	out := make([]byte, 0, q)
	for _, op := range ops {
		if op[0] == 1 {
			for i := sort.SearchInts(coords, op[1]) + 1; i < len(bit); i += i & -i {
				bit[i]++
			}
		} else {
			x, size := op[1], op[2]
			// Obstacles inside [x - size, x - 1].
			left, right := sort.SearchInts(coords, x-size), sort.SearchInts(coords, x)
			if prefix(right) == prefix(left) {
				out = append(out, '1')
			} else {
				out = append(out, '0')
			}
		}
	}
	fmt.Println(string(out))
}
